INSERT OR REPLACE INTO legacy_product_specs (id, product_id, name, capacity, form, payload_json, sort_order) VALUES ('legacy-spec-f1f2ac7721a68b1aa1fb2bb0ebf4', 'aoye', '1000ml', '1000ml', '水剂', '{"name":"1000ml","capacity":"1000ml","form":"水剂","image":"images/products/aoye_1000ml.png"}', '1');
INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('huadaifu', '花大夫', '微量元素叶面肥', '{"id":"huadaifu","name":"花大夫","category":"微量元素叶面肥","intro":"微量元素水溶肥料（水剂），打破休眠、催芽促花、防倒春寒、抗逆稳果：\n\n本品系根据作物开花阶段的生理特征及对营养元素需求进行研发的新型功能营养液肥，通过将硼和多种高活性氨基酸进行合成，并配置开花需要的微量元素，产品对离子活性和移动性有良好的增强作用，提高营养元素在植物体内的浸透作用和运转速率，有利于打破植物休眠，预防倒春寒，促进花芽分化，开花整齐，坐果稳果等作用。","description":"高硼型，B 120g/L，含Fe、Mn、Zn、Cu 0.1g/L、Mo，海藻提取物20g/L，游离氨基酸100g/L","advantages":"高硼型，促花保果针对性强；含海藻提取物和游离氨基酸：\n\n1. 独一无二的氨基酸硼配方，在低温环境下依然能保持极高的吸收利用率；\n2. 科学配比硼、锌、钼等生殖生长核心微量元素，专为作物花芽分化及开花期量身定制；\n3. 营养元素吸收转化极快，能够迅速直达花芽分化组织，激活生殖生长信号；\n4. 极高的安全性，即使在敏感的初花期及盛花期使用，也不会产生药害或烧花蕾。","ingredients":"B 120g/L、Fe 0.5g/L、Mn 0.2g/L、Zn 1g/L、Cu 0.1g/L、Mo 0.001g/L、海藻提取物20g/L、游离氨基酸100g/L","functions":"促进花芽分化、提高坐果率、保花保果、补硼：\n\n1. 打破休眠，预防倒春寒，提高植物的花芽分化效率，促进开花和结果；\n2. 有促进花粉管伸长，对授粉和果实的成型有良好的作用；\n3. 有利于促进花蕾粗壮、整齐和鲜艳，减少畸形花的发生；\n4. 具有优秀适应性和浸透作用，尽管在低温条件下，依然能保持较高吸收利用。","applicable_crops":"果树、蔬菜、油菜、豆科作物等需硼作物","usage":"1000-1200倍，或1L/400斤水，或1L/5亩地飞防20亩。液体叶面肥","price_range":"200ml/24.9元，1000ml/89.9元","mix_profile":{"ph":"9.5","has_copper":true,"copper_level":"low","has_calcium":false,"has_humic_acid":false,"has_amino_acid":true,"has_microbe":false,"has_phosphorus":false,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"深圳惠民皓天生态科技有限公司","seller":"深圳惠民皓天生态科技有限公司","origin":"中国","specifications":[{"name":"200ml","capacity":"200ml","form":"水剂","image":"images/products/huadaifu_200ml.png"},{"name":"1000ml","capacity":"1000ml","form":"水剂","image":"images/products/huadaifu_1000ml.png"}],"images":["images/products/huadaifu_200ml.png","images/products/huadaifu_1000ml.png"],"custom_fields":[{"label":"产品混用禁忌","value":"傲果"}]}', '2026-08-22T01:14:46.869Z');
