INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('guodaifu', '果大夫', '大量元素水溶肥料', '{"id":"guodaifu","name":"果大夫","category":"大量元素水溶肥料","intro":"大量元素水溶肥料（水剂），膨大、增糖、着色、美果：\n\n本品是结合果实生长期的生理特征研发的高浓缩功能营养液，通过氮磷钾、微量元素和海藻提取物合理配制而成，产品有利于调节植物生理机能，激发植物内源激素，促进维生素和花青素形成，使果实在生长期间保持丰富营养并迅速膨大均匀，增加果实糖分来促进转色均匀，增加果实的光泽度，从而提升果实品质和产量。","description":"高磷高钾，N 50g/L、P2O5 280g/L、K 400g/L，含Mg、B、Fe、Zn，海藻提取物80g/L","advantages":"高磷高钾，膨果着色双效；含海藻提取物：\n\n1. 高浓度的营养浓缩液，复配730g/L氮磷钾、微量元素和海藻提取物；\n2. 黄金膨果配方，精准匹配幼果至快速膨大期的生理营养需求比例，激发植物内源激素，迅速调节植物生理机能；\n3. 富含高活性促分裂营养因子（非激素），营养转化率极高，通过纯营养物理性拉大果实细胞；","ingredients":"N 50g/L、P2O5 280g/L、K 400g/L、Mg 2g/L、B 2g/L、Fe 3g/L、Zn 2g/L、海藻提取物80g/L","functions":"促花促果、膨果着色、提高果实品质：\n\n1. 科学合理的果实生长营养配比，满足果实生长阶段对各元素的需求；\n2. 营养丰富，补充氮磷钾和微量元素及海藻营养等 8 种以上的营养元素；\n3. 促进营养物质的同化吸收；\n4. 增加果实营养物质积累，促进膨果，增糖和转色均匀。","applicable_crops":"果树、蔬菜、瓜类等结果作物","usage":"1000-1200倍，或1L/2000斤水，或1L/25亩地。液体叶面肥","price_range":"200ml/34.9元，1000ml/124.9元","mix_profile":{"ph":"8.96","has_copper":false,"copper_level":"none","has_calcium":false,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":true,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"深圳惠民皓天生态科技有限公司","seller":"深圳惠民皓天生态科技有限公司","origin":"中国","registrations":{"execution_standard":"NY1107-2010","record_number":"DLSRGD2022-00162"},"specifications":[{"name":"200ml","capacity":"200ml","form":"水剂"},{"name":"1000ml","capacity":"1000ml","form":"水剂"}],"images":["images/products/guodaifu1000ml_800px.jpg","images/products/guodaifu200ml_800px.jpg"]}', '2026-08-22T01:14:46.869Z');
