INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('shaianxin', '晒安心', '功能肥', '{"id":"shaianxin","name":"晒安心","category":"功能肥","intro":"防晒类防护产品（粉剂），预防高温、日灼、紫外线","description":"氧化Ca 41.5%，含紫外线阻隔剂，果实防晒剂","advantages":"果实防晒专用；防紫外线、表面降温、安全环保:\n\n1.防晒与补钙双效合一，含有高含量的钙及物理紫外线阻隔剂；\n2.\t韩国进口，防晒安全且环保，防晒效果更佳；\n3.产品使用天然原料，无胶水无甲醛。","ingredients":"氧化Ca 41.5%、紫外线阻隔剂","functions":"果实防晒、延长保鲜期、减少日灼:\n\n1.预防高温日灼的发生\n2.预防因缺钙引起的生理病害\n3.促进细胞分裂，提高果肉厚度和硬度，协助着色\n4.本产品对虫害有一定的规避作用5.大幅度提高商品果率","applicable_crops":"柑橘、猕猴桃等需防晒作物","usage":"50-100倍喷雾。粉剂防晒剂，果实上喷施需确保采收前能被雨水冲掉","price_range":"500g/19.9元，5kg/169.9元","mix_profile":{"ph":"11","has_copper":false,"copper_level":"none","has_calcium":true,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":false,"has_silicon":false,"is_alkaline":true,"is_acidic":false},"manufacturer":"（株）泰京BK","seller":"深圳惠民皓天生态科技有限公司","origin":"韩国","specifications":[{"name":"500g","capacity":"500g","form":"粉剂","image":"images/products/shaianxin_500g.png"},{"name":"500g（功能版）","capacity":"500g","form":"粉剂","image":"images/products/shaianxin_500g_gongneng.png"},{"name":"500g（无品名）","capacity":"500g","form":"粉剂","image":"images/products/shaianxin_500g_wupinming.png"},{"name":"5kg","capacity":"5kg","form":"粉剂","image":"images/products/shaianxin_5kg.png"}],"images":["images/products/shaianxin_500g.png","images/products/shaianxin_500g_gongneng.png","images/products/shaianxin_500g_wupinming.png","images/products/shaianxin_5kg.png"]}', '2026-08-22T01:14:46.869Z');
