INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('aomei', '傲美', '硅肥', '{"id":"aomei","name":"傲美","category":"硅肥","intro":"含硅水溶肥料（水剂），增强抗逆性、细胞壁硅化、防虫防病:","description":"Si≥100g/L，Na≤30g/L，禾本科尤为需要","advantages":"硅≥100g/L高含量；增强细胞壁、防虫防病防倒伏:\n\n1.\t采用韩国独特优质硅资源和技术制备的水溶性离子硅酸盐，\n2.\t突破中性硅稳定性差、碱性硅适用性差的技术壁垒，吸收利用率极高,\n3.\t是国内硅肥吸收利用率最高的一款","ingredients":"Si≥100g/L、Na≤30g/L","functions":"增强抗逆性、细胞壁硅化、防虫防病、防倒伏:\n\n1. 高含量硅肥，能有效增强作物抗逆性，改善作物生长环境；\n2. 促进细胞壁硅化，提高作物抗病虫害能力，减少农药使用；\n3. 防倒伏，特别适合水稻、小麦、甘蔗等禾本科作物。","applicable_crops":"水稻、小麦、甘蔗等禾本科作物；果树蔬菜亦可","usage":"1000-1500倍，抽穗、扬花、灌浆使用3次；瓜果花芽分化、小果期、膨大期3-4次。液体叶面肥","price_range":"1000ml/139.8元","mix_profile":{"ph":"10","has_copper":false,"copper_level":"none","has_calcium":false,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":false,"has_silicon":true,"is_alkaline":true,"is_acidic":false},"manufacturer":"韩国艾玛易诺维株式会社","seller":"深圳惠民皓天生态科技有限公司","origin":"韩国","specifications":[{"name":"200ml","capacity":"200ml","form":"水剂","image":"images/products/aomei_200ml.png"},{"name":"1000ml","capacity":"1000ml","form":"水剂","image":"images/products/aomei_1000ml.png"}],"images":["images/products/aomei_200ml.png","images/products/aomei_1000ml.png"]}', '2026-08-22T01:14:46.869Z');
