INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('beineng', '蓓能', '大量元素水溶肥', '{"id":"beineng","name":"蓓能","category":"大量元素水溶肥","intro":"大量元素水溶肥（粉剂），含小分子肽，四个配方覆盖全生育期:\n韩国原装进口大量元素水溶肥，食品级原料磷酸二氢钾和硝酸钾，不含氯和硫酸根。四种配方按阶段选——高氮提苗、高磷促根促花、高钾膨果转色、平衡型全程通用。另含鱼蛋白酶解小肽和EDTA螯合微量元素，吸收率高无激素不烧苗，草莓葡萄等禁氯作物安全使用。粉剂根际肥，冲施滴灌。价格偏高不是主推产品，不能做底肥。","description":"大量元素水溶肥+鱼蛋白酶解小肽0.3%，含EDTA螯合微量元素。四个配方：高氮(30-10-10)、高磷(10-40-10)、高钾(12-6-42)、平衡(20-20-20)","advantages":"含小分子肽，吸收效率高；四配方灵活选择\n\n1.\t采用磷酸二氢钾、硝酸钾等高纯度原料，肥料吸收利用更高，肥效更持久、更安全；\n2.\t采用DS-CA复螯合技术，不易拮抗，采用OM助溶技术，溶解后形成水合离子吸收更彻底。对土壤环境伤害更小；\n3.\t复配鱼蛋白酶解小肽、海藻酸、海藻多糖，大幅提升肥料生物活性和吸收效率；\n4.\t不含激素与有害成分，长期连续使用不伤根、不导致土壤酸化板结。","ingredients":"大量元素水溶肥+鱼蛋白酶解小肽FPC 0.3%。EDTA微量元素：B 0.22%、EDTA-Fe 0.01%、EDTA-Mn 0.05%、EDTA-Cu 0.01%、EDTA-Zn 0.05%、Mo 0.001%。四个配方：高氮30-10-10、高磷10-40-10、高钾12-6-42、平衡20-20-20","functions":"提苗促长（高氮）、促根促花（高磷）、膨果转色（高钾）、营养均衡（平衡）:\n\n1. 高氮型：促进作物生长，增强叶片光合作用，提高苗期抗逆性；\n2. 高磷型：促进根系发育，增强花芽分化，提高坐果率；\n3. 高钾型：促进果实膨大和转色，提高果实品质和糖分积累；\n4. 平衡型：提供全面营养，适用于作物全程生长，保持营养均衡;\n5.快速补充作物各阶段所需的大量元素营养，精准实现提苗、促花、膨果；\n6.鱼蛋白小肽等活性成分能有效提升作物抗逆性，并显著改善果实的风味、口感和甜度；\n7.均衡树体营养，有效预防因大量结果导致的植株后期脱肥、早衰和黄化等问题，延长树体的结果年限。","applicable_crops":"果树、蔬菜、瓜类等经济作物","usage":"浇灌3-5kg/亩，7-10天一次；滴灌12-15天一次。粉剂根际肥，不做叶喷","price_range":"高氮型10kg*2袋/359元，高磷型/高钾型/平衡型10kg*2袋/359-379元","mix_profile":{"ph":"6","has_copper":true,"copper_level":"trace","has_calcium":false,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":true,"has_silicon":false,"is_alkaline":false,"is_acidic":false},"manufacturer":"韩国分享株式会社","seller":"深圳惠民皓天生态科技有限公司","origin":"韩国","specifications":[{"name":"高氮型10kg","capacity":"10kg","form":"粉剂","formula":"30-10-10+TE","image":"images/products/beineng_10kg_gaodan.png"},{"name":"高磷型10kg","capacity":"10kg","form":"粉剂","formula":"10-40-10+TE","image":"images/products/beineng_10kg_gaolin.png"},{"name":"高钾型10kg","capacity":"10kg","form":"粉剂","formula":"12-6-42+TE","image":"images/products/beineng_10kg_gaojia.png"},{"name":"平衡型10kg","capacity":"10kg","form":"粉剂","formula":"20-20-20+TE","image":"images/products/beineng_10kg_pingheng.png"}],"images":["images/products/beineng_10kg_gaodan.png","images/products/beineng_10kg_gaolin.png","images/products/beineng_10kg_gaojia.png","images/products/beineng_10kg_pingheng.png"]}', '2026-08-22T01:14:46.869Z');
