INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('aolan', '傲岚', '磷酸二氢钾', '{"id":"aolan","name":"傲岚","category":"磷酸二氢钾","intro":"磷酸二氢钾（粉剂），农用优等品，KH2PO4≥99%\n\n本品采用纯热法工艺制造，产品纯度高，易溶解、吸收快，无杂质、无重金属物质，可满足作物在不同时期对磷元素的需求。磷元素是农作物生长必需的营养元素，有助于促进农作物根系发育，促进花芽分化和开花，提升果实甜度，辅助果实转色，增强农作物的抗逆能力，属于高效又安全的大量元素营养。","description":"P2O5≥52%、K2O≥34%，高纯度磷酸二氢钾","advantages":"KH2PO4≥99%农用优等品；高纯度磷酸二氢钾","ingredients":"磷酸二氢钾（KH2PO4），P2O5≥52%、K2O≥34%","functions":"促花促果、膨果着色、增强抗逆\n\n促进根系发育：磷元素有助于促进作物根系生长，提高水分和养分吸收能力。\n促进花芽分化与开花：可辅助作物顺利完成开花、坐果等生殖生长过程。\n提升果实品质：有助于果实发育、转色和甜度积累，提升商品品质。\n增强抗逆能力：帮助作物提高对干旱、低温等不良环境的适应能力。\n纯度高、易吸收：采用纯热法工艺制造，溶解性好，吸收效率高，使用更安全。","applicable_crops":"果树、蔬菜、瓜类、大田作物均可","usage":"500倍或2-5kg/亩。粉剂，喷施为主也可冲施滴灌","price_range":"200g/9.9元，1kg/26.8元","mix_profile":{"ph":"4.5","has_copper":false,"copper_level":"none","has_calcium":false,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":true,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"深圳惠民皓天生态科技有限公司","seller":"深圳惠民皓天生态科技有限公司","origin":"中国","registrations":{"execution_standard":"HG/T2321-2016","product_grade":"农用优等品"},"specifications":[{"name":"200g","capacity":"200g","form":"粉剂","image":"images/products/aolan_200g.png"},{"name":"1kg","capacity":"1000g","form":"粉剂","image":"images/products/aolan_1kg.png"}],"images":["images/products/aolan_200g.png","images/products/aolan_1kg.png"]}', '2026-08-22T01:14:46.869Z');
