INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('jiete', '洁特', '中微量元素肥', '{"id":"jiete","name":"洁特","category":"中微量元素肥","intro":"微量元素水溶肥料（粉剂），第五代产品，铁锰锌硼同补：\n\n韩国进口中微量元素水溶肥，粉剂叶面肥。以钙为核心，复配硅、铁、锰、锌、钛等十余种元素，一次喷施补全缺素。预防黄化、裂果、软果、畸形果，促进花芽分化和保花保果，提升果实硬度和耐储性，改善果型矫正弯瓜。苗期到果期均可叶面喷施。几乎没销量不是主推，多元素补缺优先用沣硕替代。","description":"Ca 44.75%、Mg 0.66%、S 0.51%、SiO2 10.6%，含B、Fe、Mn、Zn、Cu 0.64%、Mo，P2O5≥0.15%","advantages":"第五代微量元素肥；铁锰锌硼四种元素同补:\n\n1.20种以上植物生长发育的矿物质营养和稀有元素，68%含量；\n2.钙硅及多种微量和稀有元素的补充，具有促花保果功能；\n3.对作物缺钙引起的病症及裂果具有优秀的预防能力；\n4.增强作物免疫体系，抗老化，最大程度的降低作物生理性病状；\n5.超强的农药肥料兼容混用性，安全性极高","ingredients":"Ca 44.75%、Mg 0.66%、S 0.51%、SiO2 10.6%、B 0.1%、Fe 4.34%、Mn 3%、Zn 2.56%、Cu 0.64%、Mo 0.001%、P2O5≥0.15%","functions":"补充中微量元素、钙镁硅同补、防缺素\n\n1. 补钙防裂果、软果、苦痘病 \n2. 补硅增厚细胞壁，提升抗病虫能力 \n3. 补铁锰锌预防缺素黄化和小叶簇生 \n4. 促进花芽分化，保花保果 \n5. 提升果实硬度和耐储运能力 \n6. 改善果型，矫正弯曲瓜等畸形果","applicable_crops":"果树、蔬菜、经济作物均可","usage":"苗期1500-2000倍；花期1000-1500倍；果期1000-1500倍，间隔7-15天。粉剂叶面肥","price_range":"10g*1包/9.9元，50包/盒/188元","mix_profile":{"ph":"9","has_copper":true,"copper_level":"high","has_calcium":true,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":true,"has_silicon":true,"is_alkaline":true,"is_acidic":false},"manufacturer":"韩国喜门康托思株式会社","seller":"深圳惠民皓天生态科技有限公司","origin":"韩国","registrations":{"fertilizer_registration":"外肥备案号WLSRJK2020-00057","execution_standard":"NY2266-2012","import_contract":"XW2022-P5001","customs_declaration":"52020221022009458"},"specifications":[{"name":"10g","capacity":"10g","form":"粉剂","image":"images/products/jiete_10g.png"}],"images":["images/products/jiete_10g.png"]}', '2026-08-22T01:14:46.869Z');
