INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('aotu', '傲土', '矿源黄腐酸', '{"id":"aotu","name":"傲土","category":"矿源黄腐酸","intro":"有机矿源黄腐酸（颗粒），欧盟有机认证，生根促长、调酸抑碱:\n\n西班牙进口有机矿源黄腐酸，颗粒根际肥。矿源腐殖酸和黄腐酸含量高，含水溶性钾和硅。核心功能是改良土壤，促进团粒结构形成、缓解板结和盐碱化、调节酸碱度，施后几天内可见新芽和次生根。同时增强抗旱抗寒抗病能力，硅元素增加根系吸收面积。冲施或撒施均可","description":"黄腐酸75%、矿源腐殖酸5%，水溶性钾8g/L，水溶性硅≥0.1%","advantages":"欧盟有机认证；黄腐酸75%高含量；颗粒剂型使用方便:\n\n1.矿源腐殖酸纯度高，改良土壤见效快\n2.黄腐酸与腐殖酸双重协同，既调土又促根\n3.含水溶性硅，增厚细胞壁增加根系吸收面\n4.颗粒剂型，撒施拌肥方便不飘散\n5.施后几天即可见新芽和次生根，见效速度快","ingredients":"黄腐酸75%、矿源腐殖酸5%、水溶性钾8g/L、水溶性硅≥0.1%","functions":"改良土壤结构、促根生根、提高肥料利用率:\n\n1.促进土壤团粒结构形成，缓解板结\n2.调节土壤酸碱度，改善盐碱化\n3.提升土壤保水保肥能力\n4.促进根系生长，生毛细根\n5.增强抗旱、抗寒、抗病能力\n6.硅元素增加根系吸收面积","applicable_crops":"果树、蔬菜、经济作物均可","usage":"200-300g/亩冲施；叶面800-1200倍；撒施/拌肥500-800g/亩。颗粒根际肥","price_range":"200g/29.9元","mix_profile":{"ph":"7.5","has_copper":false,"copper_level":"none","has_calcium":false,"has_humic_acid":true,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":false,"has_silicon":true,"is_alkaline":true,"is_acidic":false},"manufacturer":"ARVENSIS AGRO S.A.(SPAIN)","seller":"深圳惠民皓天生态科技有限公司","origin":"西班牙","registrations":{"certification":"欧盟有机认证（BCS OEKOGARANTIE）"},"specifications":[{"name":"200g","capacity":"200g","form":"颗粒"}],"custom_fields":[{"label":"产品混用禁忌","value":"沣硕"},{"label":"产品混用禁忌","value":"傲果"},{"label":"产品混用禁忌","value":"均施"}],"images":["images/products/傲土.jpg"]}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_product_specs (id, product_id, name, capacity, form, payload_json, sort_order) VALUES ('legacy-spec-ccd0725bc4f2dc06cdae4dd19e5d', 'aotu', '200g', '200g', '颗粒', '{"name":"200g","capacity":"200g","form":"颗粒"}', '0');
INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('aoguo', '傲果', '中量元素水溶肥料', '{"id":"aoguo","name":"傲果","category":"中量元素水溶肥料","intro":"中量元素水溶肥料（水剂），钙镁硼锌铁同补，糖醇螯合\n\n傲果是通过海藻和复合糖螯合的中微量元素肥料，具有良好的植物亲和力，见效快，易混用，分子量小，吸收利用率高。富含钙、镁、硼、锌、铁、锰、铜等营养元素，不挑作物，适合作物各个阶段使用，是农业种植中性价比高的中微量元素水溶肥料。","description":"Ca≥160g/L、Mg≥10g/L，含糖醇复合物≥100g/L（甘油糖醇、山梨糖醇、甘露醇、木糖醇），硝态氮≥80g/L，含B、Fe、Mn、Cu、Zn、Mo","advantages":"糖醇螯合钙，吸收率高；钙镁硼锌铁多元素同补\n\n1. 采用复合糖醇螯合的中微量元素，分子量小吸收快，突破常规流体钙在植物体内难移动的痛点，实现双向高效运输；\n2. 含有硝态氮，利用阴阳离子同向协同转运机制，成倍提升作物对钙、镁等金属离子的吸收速率；\n3. 除钙镁硼锌铁外，融合有锰铜钼等微量元素，进一步强化钙在细胞壁中的结构稳定作用。","ingredients":"硝态氮≥80g/L、Ca≥160g/L、Mg≥10g/L、B≥0.5g/L、Fe≥0.3g/L、Mn≥0.1g/L、Cu≥0.05g/L、Zn≥1.8g/L、Mo≥0.001g/L、复合糖醇≥100g/L（甘油糖醇、山梨糖醇、甘露醇、木糖醇）","functions":"补钙、防裂果、防脐腐病、增强果实硬度\n\n补充中微量元素，有助于作物免疫增强，促进叶片长势浓绿旺盛。\n帮助作物更好的开花、壮花，提高坐果率。\n有助于幼果快速转绿和膨大，减少因缺素导致的僵果、掉果等问题。\n有利于增强果树硬度，减少因钙缺乏导致的脐腐和开裂现象。\n促进果实均匀发育，提升果实色泽、甜度和商品品质。","applicable_crops":"苹果、葡萄、番茄、辣椒、白菜等需钙作物","usage":"叶喷800-1000倍；冲施1500g/亩，间隔10-15天。液体叶面肥","price_range":"300g/9.9元，1500g/29.9元","mix_profile":{"ph":"6","has_copper":true,"copper_level":"trace","has_calcium":true,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":false,"has_silicon":false,"is_alkaline":false,"is_acidic":false},"manufacturer":"韩国阿米诺实验室株式会社","seller":"深圳惠民皓天生态科技有限公司","origin":"韩国","specifications":[{"name":"300g","capacity":"300g","form":"水剂"},{"name":"1500g","capacity":"1500g","form":"水剂"}],"images":["images/products/傲果_1500g.png","images/products/傲果_300g.png"],"custom_fields":[{"label":"产品混用禁忌","value":"花大夫"},{"label":"产品混用禁忌","value":"傲土"}]}', '2026-08-22T01:14:46.869Z');
